"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1094-06-15:0":{"b": ["Ο Ελ Σιντ κατέλαβε τη Βαλένθια: ιδρύθηκε το Πριγκιπάτο της Βαλένθιας (Ελ Σιντ)", "f5b81beb"], "d": ["Ο Rodrigo Díaz de Vivar (Ελ Σιντ), μετά την πολιορκία, πήρε τον έλεγχο της Βαλένθιας (Valencia) στις 15 Ιουνίου 1094· στο αξίωμα του κριτή άφησε τον Ibn Jahhaf. Η Βαλένθια βγήκε από την καταγραφή των Muluk al-tawa'if (ταΐφες εμιράτα της Ανδαλουσίας) και πέρασε στο Πριγκιπάτο της Βαλένθιας (Ελ Σιντ).", "e51445ac"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-01-01:0":{"b": ["Οι Αλμοραβίδες κατέλαβαν τη Βαλένθια", "ce05cefc"], "d": ["Μετά τον θάνατο του Rodrigo το 1099, η Βαλένθια, που βρισκόταν στα χέρια της συζύγου του Ximena, καταλήφθηκε το 1102 από τους Αλμοραβίδες.", "8407a408"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-05-05:0":{"b": ["Η Βαλένθια καταλήφθηκε από τους Αλμοραβίδες (1102)", "833a9c9a"], "d": ["Μετά τον θάνατο του Ελ Σιντ το 1099, η πόλη έμεινε στη χήρα του Jimena· η Βαλένθια καταλήφθηκε από τους Αλμοραβίδες το 1102. Η Βαλένθια τότε βγαίνει από το Πριγκιπάτο της Βαλένθιας (Ελ Σιντ) και περνά στο Κράτος των Αλμοραβιδών.", "a9ecdc4d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1106-09-04:0":{"b": ["Ο Yusuf ibn Tashfin πέθανε στο Μαρακές· τον διαδέχθηκε ο γιος του Ali ibn Yusuf", "3a60ecd3"], "d": ["Ο Yusuf ibn Tashfin πέθανε στο Μαρακές· τον διαδέχθηκε ο γιος του Ali ibn Yusuf", "3a60ecd3"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1108-01-01:0":{"b": ["Ο Ali ibn Yusuf κέρδισε νίκη εναντίον του χριστιανικού στρατού στο Uclés (501, 1108).", "8380cd9c"], "d": ["Ο Ali ibn Yusuf κέρδισε νίκη εναντίον του χριστιανικού στρατού στο Uclés (501, 1108).", "8380cd9c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1110-01-24:0":{"b": ["Ο Hudide εμίρης Ahmad al-Musta'in πέθανε· αλμοραβιδικός στρατός βάδισε προς τη Σαραγόσα", "8378eeaf"], "d": ["Με τον θάνατο του Ahmad al-Musta'in-Billah (1 Rajab 503 / 24 Ιανουαρίου 1110), ένας αλμοραβιδικός στρατός κινήθηκε από τη Βαλένθια (Valencia) προς τη Σαραγόσα (Zaragoza).", "1303f83d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1112-06-28:0":{"b": ["Ο Ali ibn Yusuf πολιόρκησε το Tulaytula (Τολέδο) αλλά δεν το κατέλαβε", "d35d4a4e"], "d": ["Κατά τη δεύτερη διάβαση του Ali ibn Yusuf στην Ανδαλουσία, το Tulaytula πολιορκήθηκε· λόγω ισχυρής αντίστασης η πολιορκία άρθηκε (506/1112-13), αντίθετα καταλήφθηκαν η Μαδρίτη και μερικά κέντρα στην περιοχή της.", "106302f2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1118-12-19:0":{"b": ["Ο βασιλιάς της Αραγονίας Αλφόνσος Α' μπήκε στη Σαραγόσα· η πόλη πέρασε από τους Αλμοραβίδες στην Αραγονία", "49a4a80d"], "d": ["Η Σαραγόσα, που στο τέλος μακράς πολιορκίας εξάντλησε τα εφόδιά της, δέχθηκε τους όρους παράδοσης στις 11 Δεκεμβρίου 1118· ο Αλφόνσος Α' μπήκε στην πόλη στις 18 Δεκεμβρίου. Η Σαραγόσα έγινε πρωτεύουσα του Βασιλείου της Αραγονίας.", "25de2b0c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1121-11-13:0":{"b": ["Ο Ibn Tumart ανακήρυξε τον μεσσιανισμό (mahdiyya) του", "33dad2aa"], "d": ["Όταν ο Ibn Tumart εκδιώχθηκε από την αλμοραβιδική πρωτεύουσα Μαρακές, συγκέντρωσε οπαδούς και ανακήρυξε τον μεσσιανισμό (mahdiyya) του τον Ramadan του έτους 515 (Νοέμβριος 1121)· στα όρη Deren ξεκίνησε το κίνημα των Αλμοχάδων.", "67c9ea64"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1127-01-01:0":{"b": ["Ο βασιλιάς της Αραγονίας πολιόρκησε τη Γρανάδα αλλά αποσύρθηκε", "60877b49"], "d": ["Με παρότρυνση των χριστιανών της Γρανάδας, ο βασιλιάς της Αραγονίας πολιόρκησε την πόλη· λόγω σφοδρής άμυνας αναγκάστηκε να αποσυρθεί το 1127.", "1684bbe7"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1132-01-01:0":{"b": ["Ο βασιλιάς της Καστίλλης Αλφόνσος Ζ' λεηλάτησε τη Σεβίλλη", "23664808"], "d": ["Ο Αλφόνσος Ζ' λεηλάτησε τη Σεβίλλη το 526 (1132)· ο αλμοραβιδικός κυβερνήτης της πόλης σκοτώθηκε στις συγκρούσεις.", "342ff94a"]},
